        id={contentId}
        role="region"
        aria-labelledby={headerId}
        hidden={!isOpen}
      >
        <p>{answer}</p>
      </div>
    </div>
  );
}

function App() {
  return (
    <main className="faq-container">
      <h1>Cat FAQ</h1>
      <p className="intro">Everything you need to know about your feline friends.</p>
      <div className="faq-list">
        {faqs.map((faq, index) => (
          <FAQItem key={index} question={faq.question} answer={faq.answer} />
        ))}
      </div>
    </main>
  );
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);

